def cost(n):
    mc=ALL[n].get('mana_cost') or ''
    pips=re.findall(r'\{(.)\}',mc.split(' // ')[0]); g=sum(int(p) for p in pips if p.isdigit()); col=[p for p in pips if p in 'UBR']
    return g,col
def is_creature(n): return 'Creature' in ALL[n]['type_line']
def zombie(n): return 'Zombie' in ALL[n]['type_line']
def tough(n):
    t=ALL[n].get('toughness'); return int(t) if t and t.isdigit() else 9
def pay(srcs,g,col,zomb):
    s=[("UBR" if (x=="Z" and zomb) else ("C" if x=="Z" else x)) for x in srcs]
    if len(s)<g+len(col): return None
    col=sorted(col)
    def dfs(i,used):
        if i==len(col): return used
        for j,x in enumerate(s):
            if j not in used and col[i] in x:
                r=dfs(i+1,used|{j})
                if r is not None: return r
        return None
    used=dfs(0,frozenset())
    if used is None: return None
    rest=sorted([j for j in range(len(s)) if j not in used],key=lambda j:len(s[j]))
    return set(used)|set(rest[:g])
