def game(deck,rnd,T=7):
    global orni_t
    d=deck[:]; rnd.shuffle(d); hand=d[:7]; lib=d[7:]
    lands=[]; rocks=[]; bf=[]; orni_t=99; lord_turn=None; lord_mode=None; tokens=0; seen=7; clamp_draws=0; recs=[]
    for t in range(1,T+1):
        if t>1: hand.append(lib.pop(0)); seen+=1
        if "Bitterblossom" in bf and t>1: tokens+=1
        if "Black Market Connections" in bf: tokens+=1; hand.append(lib.pop(0)); seen+=1
        if "Ophiomancer" in bf and t>1: tokens+=0  # snake counted below as standing body
        lh=[c for c in hand if c in LAND]; newtapped=False
        if lh:
            def untapped(c):
                k=LAND[c][1]
                if k=="mtn": return any(x in MTN for x in lands)
                return k==0
            pref=sorted(lh,key=lambda c:((0 if not untapped(c) else 1) if t<=2 else (0 if untapped(c) else 1)))
            L=pref[0]; hand.remove(L); newtapped=not untapped(L); lands.append(L)
        srcs=[LAND[x][0] for i,x in enumerate(lands) if not (i==len(lands)-1 and newtapped)]
        for r in rocks: srcs+= ["C","C"] if ROCK[r]=="CC" else [ROCK[r]]
        avail=srcs[:]
        def spend(n,extra_g=0):
            nonlocal avail
            g,col=cost(n); g+=extra_g
            if n=="Lord of Tresserhorn" and "Nightscape Familiar" in bf: g=max(0,g-1)
            u=pay(avail,g,col,zombie(n) if n in ALL else False)
            if u is None: return False
            avail=[x for j,x in enumerate(avail) if j not in u]; return True
        def others(): return len([c for c in bf if is_creature(c)])+tokens+(1 if "Ophiomancer" in bf else 0)
        def try_lord():
            nonlocal lord_turn,lord_mode,avail
            if lord_turn is not None: return
            save=avail[:]
            if any(s in bf for s in SUPP):
                if spend("Lord of Tresserhorn"): lord_turn=t; lord_mode="suppressed"; return
            if others()>=2:
                if spend("Lord of Tresserhorn"): lord_turn=t; lord_mode="paid_fodder"; return
            for st,(g,col) in (("Stifle",(0,[U])),("Tale's End",(1,[U])),("Dress Down",(1,[U]))):
                if st in hand:
                    if spend("Lord of Tresserhorn"):
                        u=pay(avail,g,col,False)
                        if u is not None:
                            avail=[x for j,x in enumerate(avail) if j not in u]; hand.remove(st); lord_turn=t; lord_mode="answered_"+st; return
                        avail=save[:]
        if "Ornithopter of Paradise" in bf and t>orni_t: avail.append("UBR")
        for s in [c for c in hand if c in SUPP]:
            if spend(s): hand.remove(s); bf.append(s)
        try_lord()
        for r in sorted([c for c in hand if c in ROCK],key=lambda c:sum(cost(c)[0:1])+len(cost(c)[1])):
            if spend(r): hand.remove(r); rocks.append(r); avail+= ["C","C"] if ROCK[r]=="CC" else [ROCK[r]]
        try_lord()
        for v in sorted([c for c in hand if c in ALL and (is_creature(c) or c=="Bitterblossom") and c!="Lord of Tresserhorn"],key=lambda c:sum([cost(c)[0],len(cost(c)[1])])):
            if sum([cost(v)[0],len(cost(v)[1])])>3 and lord_turn is None and t>=3: continue
            if spend(v):
                hand.remove(v); bf.append(v)
                if v=="Ornithopter of Paradise": orni_t=t
        try_lord()
        if "Black Market Connections" in hand and spend("Black Market Connections"): hand.remove("Black Market Connections"); bf.append("Black Market Connections")
        if "Skullclamp" in hand and spend("Skullclamp"): hand.remove("Skullclamp"); bf.append("Skullclamp")
        if "Skullclamp" in bf:
            while len(avail)>=1:
                need=0 if lord_turn is not None else 2
                ones=[c for c in bf if is_creature(c) and tough(c)<=1 and c not in("Karn, Argent Defender",)]
                if others()-1<need: break
                if tokens>0: tokens-=1
                elif ones: bf.remove(ones[0])
                else: break
                avail.pop(); 
                for _ in range(2):
                    if lib: hand.append(lib.pop(0)); seen+=1; clamp_draws+=1
        lord=lord_turn is not None
        recs.append(dict(lord=lord,lord_suppressed=lord and lord_mode in("suppressed","answered_Stifle","answered_Tale's End","answered_Dress Down"),
            lord_attack_ready=lord and lord_turn<t, conv=lord and lord_turn<t and any(c in FINISH for c in hand+bf),
            freeprot=lord and any(c in hand for c in FREEPROT), anyprot=lord and any(c in hand for c in FREEPROT|{"Stubborn Denial","Slip Out the Back","Muddle the Mixture","Tale's End"}),
            seen=seen,clamp=clamp_draws))
    return recs
def run(deck,seed=29,N=20000,T=7):
    rnd=random.Random(seed); acc=collections.defaultdict(lambda: collections.Counter())
    for _ in range(N):
        for t,o in enumerate(game(deck,rnd,T),1):
            for k,v in o.items(): acc[t][k]+=v
    return {f"turn {t}":{"P_Lord_on_battlefield":round(a['lord']/N,4),"P_Lord_on_battlefield_without_paying_ETB":round(a['lord_suppressed']/N,4),
            "P_Lord_attack_ready":round(a['lord_attack_ready']/N,4),"P_Lord_attack_ready_with_conversion_card":round(a['conv']/N,4),
            "P_Lord_out_with_free_protection_in_hand":round(a['freeprot']/N,4),"P_Lord_out_with_any_counter_or_protection_in_hand":round(a['anyprot']/N,4),
            "mean_cards_seen":round(a['seen']/N,3),"mean_Skullclamp_draws":round(a['clamp']/N,3)} for t,a in acc.items()}
