# B2 conversion: Pain for All vs Temur Battle Rage vs Soul's Fire (one card in hand) + Uncaged Fury absent
def kill(card,infect,blockers,plus1,mana,opp_life,resp):
    """Single opponent target. infect: none|Phyresis_attached|Tainted_Strike_in_hand. blockers: 0|1 chump (1/1)|2 chumps.
    plus1: another +1 power source already on Lord (Shadowspear/Diregraf Captain/Skullclamp). mana: spare. resp: none|instant_removal_on_Lord_after_card_cast."""
    p=10+(1 if plus1 else 0); m=mana; inf=infect=="Phyresis_attached"
    if infect=="Tainted_Strike_in_hand" and m>=1: inf=True; p+=1; m-=1  # cast in combat after blocks / or with Soul's Fire
    if card=="Pain for All":
        if m<3: return False
        if resp!="none": return False   # aura fizzles / Lord gone before a sorcery-speed aura
        # ETB: Lord deals p damage to opponent (noncombat; precombat main so Tainted Strike also castable)
        if inf and p>=10: return True
        return p>=opp_life
    if card=="Soul's Fire":
        if m<3: return False
        if resp=="instant_removal_on_Lord_after_card_cast": return False
        # removal first: Soul's Fire is cast in response and resolves first (Lord still on the battlefield); Tainted Strike also instant
        return (inf and p>=10) or p>=opp_life
    if card=="Temur Battle Rage":
        if m<2: return False
        if resp!="none": return False
        # combat; trample from ferocious (Lord power>=4); chump 1/1 absorbs 1 per first-strike step only (dies first step)
        dmg=2*p-blockers if blockers else 2*p
        if blockers==2: dmg=2*p-2  # two 1/1 chumps: 2 lethal assigned in first strike step, both die
        return (inf and dmg>=10) or dmg>=21 or dmg>=opp_life
    if card=="none":
        if resp!="none": return False
        dmg=p if blockers==0 else 0
        return (inf and dmg>=10) or dmg>=opp_life
